INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist das Entwickeln eines Lösungskonzepts Teil der Planungsphase?', 2, '[{"text": "Ja", "correct": true, "because": "Legt Lösungsweg fest"}, {"text": "Nein", "correct": false, "because": "Es gehört zur Planung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgt das Entwickeln eines Lösungskonzepts?', 3, '[{"text": "Lösungsansatz für Projektziele definieren", "correct": true, "because": "Schafft Grundlage"}, {"text": "Team sofort einteilen", "correct": false, "because": "Späterer Schritt"}, {"text": "Kosten direkt senken", "correct": false, "because": "Kein primäres Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein Lösungskonzept löst das Problem. b) Es wird erst in der Durchführung erstellt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Planung ist entscheidend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zu einem Lösungskonzept?', 4, '[{"text": "Beschreibung der Lösung", "correct": true, "because": "Definiert Ansatz"}, {"text": "Unklare Vorschläge", "correct": false, "because": "Fehlt Präzision"}, {"text": "Technische Umsetzung", "correct": true, "because": "Zeigt Machbarkeit"}, {"text": "Zieldefinition", "correct": true, "because": "Verknüpft mit Zielen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Projekt ohne Lösungskonzept geplant werden?', 2, '[{"text": "Nein", "correct": true, "because": "Lösungsweg fehlt"}, {"text": "Ja", "correct": false, "because": "Risiko von Fehlern"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Lösungskonzept ist schlecht entwickelt?', 3, '[{"text": "Irgendwas wird schon passen", "correct": true, "because": "Zu ungenau"}, {"text": "Datenbank mit SQL bis Juni", "correct": false, "because": "Klar und spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist ein Lösungskonzept nur für technische Projekte relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch organisatorische Lösungen"}, {"text": "Ja", "correct": false, "because": "Breite Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode unterstützt das Entwickeln eines Lösungskonzepts?', 3, '[{"text": "Brainstorming", "correct": true, "because": "Fördert Ideen"}, {"text": "Keine Analyse", "correct": false, "because": "Fehlt Grundlage"}, {"text": "Zufällige Wahl", "correct": false, "because": "Ungenau"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein Lösungskonzept berücksichtigt Anforderungen. b) Es ist immer unveränderlich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, flexibel anpassbar"}, {"text": "Beides stimmt", "correct E": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt das Lösungskonzept in der Planung?', 3, '[{"text": "Grundlage für Umsetzung", "correct": true, "because": "Leitet Schritte"}, {"text": "Motivation steigern", "correct": false, "because": "Anderer Fokus"}, {"text": "Kosten direkt festlegen", "correct": false, "because": "Späterer Schritt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Lösungskonzept ohne Problemverständnis erstellt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Problem ist Basis"}, {"text": "Ja", "correct": false, "because": "Fehlende Grundlage"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel zeigt ein gutes Lösungskonzept?', 3, '[{"text": "Backup-System mit täglichem Plan", "correct": true, "because": "Klar und konkret"}, {"text": "Irgendwas sichern", "correct": false, "because": "Zu vage"}, {"text": "Team soll etwas finden", "correct": false, "because": "Nicht spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist das Lösungskonzept nur für den Projektleiter wichtig?', 2, '[{"text": "Nein", "correct": true, "because": "Team braucht Orientierung"}, {"text": "Ja", "correct": false, "because": "Projektweite Relevanz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten hat ein Lösungskonzept?', 4, '[{"text": "Lösungsbeschreibung", "correct": true, "because": "Definiert Ansatz"}, {"text": "Vage Ideen", "correct": false, "because": "Fehlt Klarheit"}, {"text": "Ressourceneinsatz", "correct": true, "because": "Plant Umsetzung"}, {"text": "Risikobetrachtung", "correct": true, "because": "Minimiert Gefahren"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss ein Lösungskonzept dokumentiert werden?', 2, '[{"text": "Ja", "correct": true, "because": "Nachvollziehbarkeit nötig"}, {"text": "Nein", "correct": false, "because": "Dokumentation hilft"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktion hat ein Lösungskonzept?', 3, '[{"text": "Weg zur Zielerreichung zeigen", "correct": true, "because": "Leitet Umsetzung"}, {"text": "Zeit verlängern", "correct": false, "because": "Kein Ziel"}, {"text": "Teamgröße festlegen", "correct": false, "because": "Späterer Schritt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Lösungskonzept mehrere Lösungen enthalten?', 2, '[{"text": "Ja", "correct": true, "because": "Alternativen möglich"}, {"text": "Nein", "correct": false, "because": "Flexibilität erlaubt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor erschwert das Entwickeln eines Lösungskonzepts?', 3, '[{"text": "Unklare Anforderungen", "correct": true, "because": "Fehlende Basis"}, {"text": "Klarer Zeitplan", "correct": false, "because": "Fördert Struktur"}, {"text": "Gute Ressourcen", "correct": false, "because": "Unterstützt Entwicklung"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein Lösungskonzept berücksichtigt Ressourcen. b) Es ist nur für IT-Projekte.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, breit anwendbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Nutzen eines Lösungskonzepts?', 3, '[{"text": "Klare Umsetzungsstrategie", "correct": true, "because": "Fördert Planung"}, {"text": "Maximale Unklarheit", "correct": false, "because": "Widerspricht Zweck"}, {"text": "Keine Richtung", "correct": false, "because": "Gibt Orientierung"}]');
